mapper.select:
SELECT a.ALLOCATION_ID as allocationId, a.ALLOCATION_NO as allocationNo, a.ALLOCATION_PERIOD as allocationPeriod, a.SOURCE_CENTER_ID as sourceCenterId, sc.CENTER_NAME as sourceCenterName, a.ALLOCATION_METHOD as allocationMethod, a.TOTAL_AMOUNT as totalAmount, a.ALLOCATION_STATUS as allocationStatus, a.ALLOCATION_DATE as allocationDate, a.IS_GENERATE_VOUCHER as isGenerateVoucher, a.VOUCHER_ID as voucherId, a.REMARK as remark, a.CREATE_TIME as createTime, a.UPDATE_TIME as updateTime, -- 统计信息 COALESCE(d.target_center_count, 0) as targetCenterCount, COALESCE(d.total_allocated_amount, a.TOTAL_AMOUNT) as totalAllocatedAmount FROM T_COST_ALLOCATION a LEFT JOIN T_COST_CENTER sc ON a.SOURCE_CENTER_ID = sc.CENTER_ID AND sc.IS_DELETED = 0 LEFT JOIN ( SELECT ALLOCATION_ID, COUNT(*) as target_center_count, SUM(ALLOCATED_AMOUNT) as total_allocated_amount FROM T_COST_ALLOCATION_DETAIL WHERE IS_DELETED = 0 GROUP BY ALLOCATION_ID ) d ON a.ALLOCATION_ID = d.ALLOCATION_ID WHERE a.IS_DELETED = 0
AND a.BOOK_ID = CAST(#{param.bookId} AS NUMBER)
AND a.TENANT_ID = CAST(#{param.tenantId} AS NUMBER)
AND a.ALLOCATION_PERIOD = #{param.allocationPeriod}
AND a.ALLOCATION_NO LIKE '%' || #{param.allocationNo} || '%'
AND a.SOURCE_CENTER_ID = CAST(#{param.sourceCostCenterId} AS NUMBER)
AND a.ALLOCATION_METHOD = #{param.allocationMethod}
AND a.ALLOCATION_STATUS = #{param.allocationStatus}
AND a.IS_GENERATE_VOUCHER = #{param.isGenerateVoucher}
AND a.ALLOCATION_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND a.ALLOCATION_DATE <= TO_DATE(#{endDate}, 'YYYY-MM-DD')
AND a.TOTAL_AMOUNT >= #{param.minAmount}
AND a.TOTAL_AMOUNT <= #{param.maxAmount}
AND a.CREATOR = #{param.creator}
AND a.REMARK LIKE '%' || #{param.remark} || '%'
AND a.SOURCE_CENTER_ID IN
CAST(#{centerId} AS NUMBER)
AND a.CREATOR = #{param.currentUserId}
ORDER BY a.ALLOCATION_DATE DESC, a.ALLOCATION_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM T_COST_ALLOCATION a
WHERE a.IS_DELETED = 0

    AND a.BOOK_ID = CAST(#{param.bookId} AS NUMBER)


    AND a.TENANT_ID = CAST(#{param.tenantId} AS NUMBER)


    AND a.ALLOCATION_PERIOD = #{param.allocationPeriod}


    AND a.ALLOCATION_NO LIKE '%' || #{param.allocationNo} || '%'


    AND a.SOURCE_CENTER_ID = CAST(#{param.sourceCostCenterId} AS NUMBER)


    AND a.ALLOCATION_METHOD = #{param.allocationMethod}


    AND a.ALLOCATION_STATUS = #{param.allocationStatus}


    AND a.IS_GENERATE_VOUCHER = #{param.isGenerateVoucher}


    AND a.ALLOCATION_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')


    AND a.ALLOCATION_DATE  <=  TO_DATE(#{endDate}, 'YYYY-MM-DD')


    AND a.TOTAL_AMOUNT >= #{param.minAmount}


    AND a.TOTAL_AMOUNT  <=  #{param.maxAmount}


    AND a.CREATOR = #{param.creator}


    AND a.REMARK LIKE '%' || #{param.remark} || '%'



    AND a.SOURCE_CENTER_ID IN

        CAST(#{centerId} AS NUMBER)



    AND a.CREATOR = #{param.currentUserId}

mapper.update:
UPDATE T_COST_ALLOCATION SET ALLOCATION_STATUS = #{status}, UPDATE_TIME = SYSDATE, UPDATER = #{updater} WHERE ALLOCATION_ID IN
#{allocationId}
AND IS_DELETED = 0

UPDATE T_COST_ALLOCATION SET ALLOCATION_STATUS = #{status}, ALLOCATION_DATE = TO_DATE(#{allocationDate}, 'YYYY-MM-DD HH24:MI:SS'), UPDATE_TIME = SYSDATE, UPDATER = #{updater} WHERE ALLOCATION_ID IN
#{allocationId}
AND IS_DELETED = 0 AND ALLOCATION_STATUS < 3

UPDATE T_COST_ALLOCATION
SET IS_DELETED = 1,
    UPDATE_TIME = SYSDATE,
    UPDATER = #{updater}
WHERE ALLOCATION_ID = #{allocationId}
  AND IS_DELETED = 0

UPDATE T_COST_ALLOCATION SET IS_DELETED = 1, UPDATE_TIME = SYSDATE, UPDATER = #{updater} WHERE ALLOCATION_ID IN
#{allocationId}
AND IS_DELETED = 0

UPDATE T_COST_ALLOCATION_DETAIL
SET IS_DELETED = 1,
    UPDATE_TIME = SYSDATE,
    UPDATER = #{updater}
WHERE ALLOCATION_ID = #{allocationId}
  AND IS_DELETED = 0

mapper.select:
SELECT COALESCE(SUM(a.TOTAL_AMOUNT), 0) AS "totalAmount", COUNT(a.ALLOCATION_ID) AS "allocationCount", COUNT(DISTINCT a.SOURCE_CENTER_ID) AS "centerCount", COUNT(DISTINCT a.SOURCE_CENTER_ID) AS "activeCenters", CASE WHEN COUNT(a.ALLOCATION_ID) > 0 THEN ROUND(COUNT(DISTINCT a.SOURCE_CENTER_ID) * 100.0 / COUNT(a.ALLOCATION_ID), 2) ELSE 0 END AS "avgAllocationRate", 0 AS "growthRate" FROM T_COST_ALLOCATION a WHERE a.IS_DELETED = 0 AND a.ALLOCATION_PERIOD = #{period}
AND a.BOOK_ID = CAST(#{bookId} AS NUMBER)
AND a.TENANT_ID = CAST(#{tenantId} AS NUMBER)

mapper.update:
UPDATE T_COST_ALLOCATION
SET VOUCHER_ID = #{voucherId},
    UPDATE_TIME = SYSDATE,
    UPDATER = #{updater}
WHERE ALLOCATION_ID = #{allocationId}
  AND IS_DELETED = 0

mapper.select:
SELECT TO_CHAR(ca.ALLOCATION_ID) AS ALLOCATION_ID, ca.ALLOCATION_PERIOD, sc.CENTER_CODE AS SOURCE_CENTER_CODE, sc.CENTER_NAME AS SOURCE_CENTER_NAME, tc.CENTER_CODE AS TARGET_CENTER_CODE, tc.CENTER_NAME AS TARGET_CENTER_NAME, ca.ALLOCATION_AMOUNT, ca.ALLOCATION_RATIO, CASE ca.ALLOCATION_METHOD WHEN 1 THEN '平均分摊' WHEN 2 THEN '按比例分摊' WHEN 3 THEN '定额分摊' ELSE '其他' END AS ALLOCATION_METHOD_NAME, CASE ca.ALLOCATION_STATUS WHEN 1 THEN '待分摊' WHEN 2 THEN '分摊中' WHEN 3 THEN '已分摊' WHEN 4 THEN '已审核' ELSE '未知' END AS STATUS_NAME, u.REALNAME AS AUDITOR_NAME, ca.AUDIT_TIME, ca.CREATE_TIME, TO_CHAR(ca.BOOK_ID) AS BOOK_ID FROM "REDACTED"."T_COST_ALLOCATION" ca LEFT JOIN "REDACTED"."T_COST_CENTER" sc ON ca.SOURCE_CENTER_ID = sc.CENTER_ID LEFT JOIN "REDACTED"."T_COST_CENTER" tc ON ca.TARGET_CENTER_ID = tc.CENTER_ID LEFT JOIN TBL_STAFF u ON ca.AUDITOR_ID = u.STAFFID WHERE ca.ALLOCATION_STATUS = 4
AND ca.ALLOCATION_PERIOD = #{allocationPeriod}
AND ca.BOOK_ID = #{bookId}
AND ca.TENANT_ID = #{tenantId}
ORDER BY ca.CREATE_TIME DESC
